68	 */
69	
70	@RestController
71	@CrossOrigin(exposedHeaders = "errors, content-type")
72	@RequestMapping("/api")
73	public class OwnerRestControllerV1 implements OwnersApi {
74	
75	    /** Maximum number of owners a single city may contain; creating an owner in a city that
76	     *  already has this many owners is rejected with 409 Conflict. */
77	    private static final int MAX_OWNERS_PER_CITY = 50;
78	
79	    /** Maximum number of owners that may be created on a single day (by registration date); creating
80	     *  an owner once this many owners already carry today's registration date is rejected with
81	     *  429 Too Many Requests. */
82	    private static final int MAX_OWNERS_PER_DAY = 100;
83	
84	    /** When more than this many owners already carry today's registration date at creation time, the
85	     *  new owner's 'bulkSignupWarning' flag is set true; otherwise it is false. */
86	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
87	
88	    /** Disposable email domains that are not accepted for an owner; a create whose email domain is on
89	     *  this blocklist is rejected with 400 Bad Request. Compared case-insensitively (lower-cased). */
90	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
91	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
92	
93	    /** Dedicated audit logger; a line is emitted here for each successful owner create. */
94	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
95	
96	    private final ClinicService clinicService;
97	
98	    private final OwnerMapper ownerMapper;
99	
100	    private final PetMapper petMapper;
101	
102	    private final VisitMapper visitMapper;
103	
104	    private final TelephoneNormalizer telephoneNormalizer;
105	
106	    private final HouseholdNormalizer householdNormalizer;
107	
108	    private final AddressNormalizer addressNormalizer;
109	
110	    private final EmailNormalizer emailNormalizer;
111	
112	    public OwnerRestControllerV1(ClinicService clinicService,
113	                                 OwnerMapper ownerMapper,
114	                                 PetMapper petMapper,
115	                                 VisitMapper visitMapper,
116	                                 TelephoneNormalizer telephoneNormalizer,
117	                                 HouseholdNormalizer householdNormalizer,
118	                                 AddressNormalizer addressNormalizer,
119	                                 EmailNormalizer emailNormalizer) {
120	        this.clinicService = clinicService;
121	        this.ownerMapper = ownerMapper;
122	        this.petMapper = petMapper;
123	        this.visitMapper = visitMapper;
124	        this.telephoneNormalizer = telephoneNormalizer;
125	        this.householdNormalizer = householdNormalizer;
126	        this.addressNormalizer = addressNormalizer;
127	        this.emailNormalizer = emailNormalizer;
128	    }
129	
130	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
131	    @Override
132	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
133	        Collection<Owner> owners;
134	        if (lastName != null) {
135	            owners = this.clinicService.findOwnerByLastName(lastName);
136	        } else {
137	            owners = this.clinicService.findAllOwners();
138	        }
139	        if (owners.isEmpty()) {
140	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
141	        }
142	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
143	    }
144	
145	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
146	    @Override
147	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
148	        Owner owner = this.clinicService.findOwnerById(ownerId);
149	        if (owner == null) {
150	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
151	        }
152	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
153	    }
154	
155	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
156	    @Override
157	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
158	        HttpHeaders headers = new HttpHeaders();
159	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
160	        normalizeOwnerFields(owner);
161	        // Enforce the pre-persistence policies that can reject the new owner outright.
162	        rejectDisallowedOwnerCreation(owner);
163	        // Resolve the owner's household membership: assign the deterministic 'householdId' (a pure
164	        // function of last name and postcode), reject a household duplicate unless the request
165	        // declares it shares the household, and record the household size. This runs before the
166	        // identity-key check so that check sees the owner's household id.
167	        boolean declaredHouseholdMember =
168	            applyHouseholdMembership(owner, Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()));
169	        // Reject the create when the owner's whole derived identity key (normalized telephone,
170	        // email and household id) already matches an existing owner. This single rule subsumes the
171	        // former separate telephone, email and household duplicate checks.
172	        rejectWhenIdentityInUse(owner);
173	        // Flag the owner as a possible (soft) duplicate when, although not a hard duplicate, it
174	        // shares an existing owner's last name and postcode with a different telephone. A declared
175	        // household member is never flagged: it is a known member, not a suspected duplicate.
176	        assignPossibleDuplicate(owner, declaredHouseholdMember);
177	        // Assign the remaining create-time derived fields (namesake count, customer code,
178	        // membership number and bulk-signup warning), each fixed at creation time.
179	        assignDerivedFields(owner);
180	        this.clinicService.saveOwner(owner);
181	        // Emit an audit line for the successful create, carrying the owner id, customer code and
182	        // registration date so the create can be traced from the dedicated AUDIT log.
183	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={}",
184	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
185	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
186	        headers.setLocation(UriComponentsBuilder.newInstance()
187	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
188	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
189	    }
190	
191	    /**
192	     * Enforces the pre-persistence policies that reject a newly mapped and normalized owner
193	     * outright, in order, before any derived fields are assigned or the owner is saved. Each
194	     * independent rule lives in its own {@code rejectWhen...} guard and is applied here in order, so
195	     * the sequence of create-time rejections stays readable and a new rule is added as one more
196	     * guard. Grouping the rules here keeps {@link #addOwner} focused on the household, derived-field
197	     * and persistence steps. The single duplicate rule that rejects an owner whose whole identity
198	     * key matches an existing one is applied separately in {@link #rejectWhenIdentityInUse}, after
199	     * the household id has been resolved, because that key includes the household id.
200	     *
201	     * @param owner the newly mapped and normalized owner being created
202	     */
203	    private void rejectDisallowedOwnerCreation(Owner owner) {
204	        rejectWhenDailyLimitReached(owner);
205	        rejectWhenCityAtCapacity(owner);
206	    }
207	
208	    /**
209	     * Applies the household-membership rules for a newly normalized owner being created. The
210	     * household id is a deterministic function of the owner's last name and postcode, so owners
211	     * with the same last name and postcode share it automatically; it is assigned to the new owner
212	     * here. Because the household is keyed on (last name, postcode), any existing owner with the
213	     * same last name and postcode is a member of the same household: a second such owner is rejected
214	     * as a household duplicate (409) unless the request declares it shares the household via
215	     * {@code sharesHousehold}, in which case it is created as a declared household member. The
216	     * owner's {@code householdSize} (the number of owners sharing the household after this create)
217	     * is recorded either way. The assigned household id is part of the owner's identity key, so it
218	     * is resolved here before {@link #rejectWhenIdentityInUse}.
219	     *
220	     * @param owner           the newly mapped and normalized owner being created
221	     * @param sharesHousehold whether the request declared that the owner shares an existing household
222	     * @return {@code true} if the owner joined an existing household as a declared member
223	     */
224	    private boolean applyHouseholdMembership(Owner owner, boolean sharesHousehold) {
225	        // Assign the deterministic household id (a pure function of last name and postcode) so every
226	        // owner with the same last name and postcode shares it automatically.
227	        owner.setHouseholdId(householdNormalizer.householdId(owner.getLastName(), owner.getPostcode()));
228	        // Identify any existing owners in the same household (same computed household id).
229	        List<Owner> householdMembers = sameHouseholdOwners(owner);
230	        // A second owner in an existing household is a household duplicate: reject it with 409 unless
231	        // the request declares it shares the household, in which case create it as a declared member.
232	        boolean declaredHouseholdMember = false;
233	        if (!householdMembers.isEmpty()) {
234	            if (!sharesHousehold) {
235	                throw new HouseholdDuplicateException(
236	                    "An owner in the household " + owner.getHouseholdId() + " already exists");
237	            }
238	            declaredHouseholdMember = true;
239	        }
240	        // Record the size of this owner's household after this create, fixed at creation time.
241	        owner.setHouseholdSize(householdMembers.size() + 1);
242	        return declaredHouseholdMember;
243	    }
244	
245	    /**
246	     * Assigns the create-time derived fields of a newly normalized owner whose household membership
247	     * has already been resolved: the namesake count, the per-city customer code, the membership
248	     * number derived from that customer code and the registration year, and the bulk-signup warning
249	     * flag. Each value is fixed at creation time and is independent of the others. Grouping them
250	     * here keeps {@link #addOwner} focused on the high-level create sequence.
251	     *
252	     * @param owner the owner being created, already normalized and with its household resolved
253	     */
254	    private void assignDerivedFields(Owner owner) {
255	        // Record how many existing owners already share this owner's first and last name
256	        // (compared case-insensitively) before this create, fixed at creation time.
257	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
258	        // Assign the customer code '<REGION>-<HASH8>' from the region derived from the postcode
259	        // and an 8-hex-character hash of the normalized telephone and last name, fixed at creation
260	        // time.
261	        owner.setCustomerCode(customerCode(owner));
262	        // Assign the membership number '<customerCode>-M<YY>', where YY is the last two digits
263	        // of the registration date's year (e.g. 'NSW-A1B2C3D4-M26'), fixed at creation time.
264	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
265	        // Flag the create when more than 80 owners have already been created on this owner's
266	        // (adjusted business-day) registration date, fixed at creation time.
267	        owner.setBulkSignupWarning(
268	            countOwnersRegisteredOn(owner.getRegistrationDate()) > BULK_SIGNUP_WARNING_THRESHOLD);
269	    }
270	
271	    /**
272	     * Rejects creating an owner whose whole derived identity key already matches an existing owner,
273	     * with 409 Conflict. The identity key ({@link Owner#getIdentityKey()}) joins the normalized
274	     * telephone, the email (or empty) and the household id (or empty), so this single rule replaces
275	     * the former separate telephone, email and household duplicate checks: two owners collide only
276	     * when their whole keys are equal, and members of one household with different telephones have
277	     * different keys and are both allowed.
278	     *
279	     * @param owner the owner being created, already normalized and with its household resolved
280	     */
281	    private void rejectWhenIdentityInUse(Owner owner) {
282	        String identityKey = owner.getIdentityKey();
283	        boolean inUse = existingOwners()
284	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
285	        if (inUse) {
286	            throw new DuplicateIdentityException(
287	                "An owner with identity key " + identityKey + " already exists");
288	        }
289	    }
290	
291	    /**
292	     * Assigns the soft-duplicate flags for a newly normalized owner that has already passed the hard
293	     * duplicate (identity-key) check. When an existing owner shares this owner's last name (compared
294	     * case-insensitively) and postcode but carries a different (normalized) telephone, the new owner
295	     * is still created but flagged as a possible duplicate: {@code possibleDuplicate} is set true and
296	     * {@code possibleDuplicateOf} to the matching owner's id (the lowest such id when several match).
297	     * Otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf} is left absent.
298	     * A postcode is required on both sides for a match, so an owner without a postcode is never a
299	     * possible duplicate. A declared household member is never flagged: it is a known member of the
300	     * household, not a suspected duplicate. Both values are fixed at creation time.
301	     *
302	     * @param owner                   the owner being created, already normalized and confirmed not a
303	     *                                hard duplicate
304	     * @param declaredHouseholdMember whether the owner joined an existing household as a declared
305	     *                                member
306	     */
307	    private void assignPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
308	        Integer matchId = declaredHouseholdMember || owner.getPostcode() == null ? null : existingOwners()
309	            .filter(existing -> isPossibleDuplicateOf(existing, owner))
310	            .map(Owner::getId)
311	            .min(Integer::compareTo)
312	            .orElse(null);
313	        owner.setPossibleDuplicate(matchId != null);
314	        owner.setPossibleDuplicateOf(matchId);
315	    }
316	
317	    /**
318	     * Tests whether an existing owner makes the owner being created a possible (soft) duplicate: the
319	     * two share a postcode (required on both sides, so an owner without a postcode never matches) and
320	     * a last name (compared case-insensitively) but carry different (normalized) telephones. A match
321	     * flags the new owner as a possible duplicate of the existing one without rejecting the create.
322	     *
323	     * @param existing an existing owner to compare against
324	     * @param owner    the owner being created
325	     * @return {@code true} if the existing owner makes the new owner a possible duplicate
326	     */
327	    private boolean isPossibleDuplicateOf(Owner existing, Owner owner) {
328	        return existing.getPostcode() != null
329	            && existing.getPostcode().equals(owner.getPostcode())
330	            && existing.getLastName() != null
331	            && existing.getLastName().equalsIgnoreCase(owner.getLastName())
332	            && existing.getTelephone() != null
333	            && !existing.getTelephone().equals(owner.getTelephone());
334	    }
335	
336	    /**
337	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners already carry this
338	     * owner's adjusted business-day registration date, with 429 Too Many Requests.
339	     *
340	     * @param owner the owner being created
341	     */
342	    private void rejectWhenDailyLimitReached(Owner owner) {
343	        if (countOwnersRegisteredOn(owner.getRegistrationDate()) >= MAX_OWNERS_PER_DAY) {
344	            throw new DailyOwnerLimitExceededException(
345	                "The maximum number of owners that may be created today has already been reached");
346	        }
347	    }
348	
349	    /**
350	     * Rejects creating an owner when the owner's city already contains {@link #MAX_OWNERS_PER_CITY}
351	     * or more owners, with 409 Conflict.
352	     *
353	     * @param owner the owner being created
354	     */
355	    private void rejectWhenCityAtCapacity(Owner owner) {
356	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
357	            throw new CityCapacityExceededException(
358	                "The city " + owner.getCity() + " already contains the maximum number of owners");
359	        }
360	    }
361	
362	    /**
363	     * Canonicalizes the fields of a newly mapped owner on create, in place, so each value is
364	     * persisted and returned in its canonical form. The address is normalized (trimmed, whitespace
365	     * collapsed, upper-cased and common abbreviations expanded, rejecting a value blank after
366	     * normalization with 400), the telephone is normalized to E.164 (rejecting an unformattable
367	     * value with 400), the email is lower-cased, and a missing registration date defaults to the
368	     * server's current date. Canonicalising the address here, before the household checks read it,
369	     * ensures duplicate detection and the shared household id both compare the normalized form.
370	     * Centralising these per-field canonicalizations here keeps {@link #addOwner} focused on the
371	     * duplicate, household and customer-code rules.
372	     *
373	     * @param owner the newly mapped owner to canonicalize
374	     */
375	    private void normalizeOwnerFields(Owner owner) {
376	        // Normalize the address on create so it is stored and returned in canonical form and every
377	        // later comparison (household duplicate detection and the shared household id) uses it.
378	        // A value that is blank after normalization is rejected with 400.
379	        owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
380	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
381	        // A value that cannot form a valid E.164 number, or whose national-number length is wrong
382	        // for its country code (+61 => 9 national digits, +1 => 10), is rejected with 400.
383	        owner.setTelephone(telephoneNormalizer.normalizeAndValidate(owner.getTelephone()));
384	        // Store the (already syntactically validated) email lower-cased so it is persisted and
385	        // returned in canonical form. A missing email is left untouched.
386	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
387	        // Reject an email whose domain is on the disposable-domain blocklist with 400, after
388	        // canonicalization so the comparison sees the lower-cased value.
389	        rejectDisposableEmailDomain(owner.getEmail());
390	        // Validate the optional postcode against the fixed range for the city's region. A postcode
391	        // is checked only when present (it is optional); one out of range for the city's region is
392	        // rejected with 400. A city with no known region accepts any 4-digit postcode. The stored
393	        // value is left unchanged.
394	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
395	        // Reject a supplied registration date that is later than the server's current date with
396	        // 400, before any defaulting or business-day adjustment, so a future date is never
397	        // persisted regardless of how the roll-forward would move it.
398	        rejectFutureRegistrationDate(owner.getRegistrationDate());
399	        // Default the registration date to the server's current date when the client did not
400	        // supply one, then roll the effective date forward to a business day so a Saturday or
401	        // Sunday (whether supplied or defaulted) becomes the following Monday. The adjusted date
402	        // is persisted and returned in ISO 'YYYY-MM-DD' form and is the value every registration-
403	        // date-derived field (such as the membership number's year segment) and the per-day
404	        // create-limit are computed from.
405	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() == null
406	            ? java.time.LocalDate.now() : owner.getRegistrationDate();
407	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
408	    }
409	
410	    /**
411	     * Rejects a supplied email whose domain is on the disposable-domain blocklist
412	     * ({@link #DISPOSABLE_EMAIL_DOMAINS}) with a 400 Bad Request. The email is already canonicalized
413	     * (lower-cased) here, so the domain — the part after the final {@code '@'} — is compared directly
414	     * against the lower-cased blocklist. A {@code null} email (email is optional) or one without a
415	     * domain part is left untouched.
416	     *
417	     * @param email the owner's canonicalized email, or {@code null} when absent
418	     */
419	    private void rejectDisposableEmailDomain(String email) {
420	        if (email == null) {
421	            return;
422	        }
423	        int at = email.lastIndexOf('@');
424	        if (at < 0) {
425	            return;
426	        }
427	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
428	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
429	            throw new DisposableEmailException(
430	                "The supplied email domain " + domain + " is on the disposable-domain blocklist");
431	        }
432	    }
433	
434	    /**
435	     * Rejects a supplied registration date that is later than the server's current date with a
436	     * 400 Bad Request. A missing registration date (defaulted to the server date later) is
437	     * accepted, and a date on or before today is left for the normal defaulting and business-day
438	     * adjustment.
439	     *
440	     * @param registrationDate the client-supplied registration date, or {@code null} when absent
441	     */
442	    private void rejectFutureRegistrationDate(java.time.LocalDate registrationDate) {
443	        if (registrationDate != null && registrationDate.isAfter(java.time.LocalDate.now())) {
444	            throw new InvalidRegistrationDateException(
445	                "The supplied registration date " + registrationDate + " is later than the current date");
446	        }
447	    }
448	
449	    /**
450	     * Rolls a registration date forward to a business day: a Saturday or Sunday advances to the
451	     * following Monday, while a weekday is returned unchanged. Applied to the effective
452	     * registration date (whether supplied in the request or defaulted to the server date) so the
453	     * persisted registration date, every value derived from it and the per-day create-limit all
454	     * use the adjusted business day.
455	     *
456	     * @param date the effective registration date
457	     * @return the same date if it is a weekday, otherwise the following Monday
458	     */
459	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
460	        java.time.LocalDate adjusted = date;
461	        while (adjusted.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
462	            || adjusted.getDayOfWeek() == java.time.DayOfWeek.SUNDAY) {
463	            adjusted = adjusted.plusDays(1);
464	        }
465	        return adjusted;
466	    }
467	
468	    /**
469	     * Builds the customer code '<REGION>-<HASH8>' for a newly created owner, where REGION is the
470	     * region derived from the owner's postcode (falling back to the city, via
471	     * {@link LocalityResolver}) and HASH8 is the first 8 upper-case hex characters of the SHA-256
472	     * digest over the owner's normalized telephone concatenated with the last name (e.g.
473	     * 'NSW-A1B2C3D4'). When that base code already belongs to an existing owner, '-<n>' is appended
474	     * with the smallest n of 2 or more that makes it unique, so distinct owners always receive
475	     * distinct customer codes.
476	     *
477	     * @param owner the owner being created, already normalized
478	     * @return the formatted, de-duplicated customer code
479	     */
480	    private String customerCode(Owner owner) {
481	        String region = LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
482	        String hash8 = Sha256Hex.upperHexPrefix(owner.getTelephone() + owner.getLastName(), 8);
483	        String base = region + "-" + hash8;
484	        Set<String> taken = existingOwners()
485	            .map(Owner::getCustomerCode)
486	            .filter(code -> code != null)
487	            .collect(Collectors.toSet());
488	        if (!taken.contains(base)) {
489	            return base;
490	        }
491	        int n = 2;
492	        while (taken.contains(base + "-" + n)) {
493	            n++;
494	        }
495	        return base + "-" + n;
496	    }
497	
498	    /**
499	     * Streams the existing owners that the create-time rules match a new owner against. Every
500	     * duplicate, quota and derived-field rule scans this same set of owners and differs only in the
501	     * predicate it applies, so fetching them is centralized here to keep each rule focused on its
502	     * own matching criterion rather than on how the existing owners are retrieved.
503	     *
504	     * @return a stream over all existing owners
505	     */
506	    private Stream<Owner> existingOwners() {
507	        return this.clinicService.findAllOwners().stream();
508	    }
509	
510	    /**
511	     * Counts the existing owners located in the given city, compared case-insensitively. Used to
512	     * fix the per-city sequence of an owner's customer code at creation time.
513	     *
514	     * @param city the city of the owner being created
515	     * @return the number of existing owners in a matching city
516	     */
517	    private int countOwnersInCity(String city) {
518	        return (int) existingOwners()
519	            .filter(existing -> existing.getCity() != null
520	                && existing.getCity().equalsIgnoreCase(city))
521	            .count();
522	    }
523	
524	    /**
525	     * Counts the existing owners whose registration date is the given adjusted business day. Used
526	     * to enforce the per-day cap that rejects creating an owner once {@link #MAX_OWNERS_PER_DAY}
527	     * owners already carry that business day as their registration date.
528	     *
529	     * @param date the adjusted business-day registration date to match
530	     * @return the number of existing owners registered on that date
531	     */
532	    private int countOwnersRegisteredOn(java.time.LocalDate date) {
533	        return (int) existingOwners()
534	            .filter(existing -> date.equals(existing.getRegistrationDate()))
535	            .count();
536	    }
537	
538	    /**
539	     * Builds the membership number '<customerCode>-M<YY>' for a newly created owner, where YY is
540	     * the last two digits of the registration date's year (e.g. 'NSW-A1B2C3D4-M26').
541	     *
542	     * @param customerCode     the owner's customer code
543	     * @param registrationDate the owner's registration date
544	     * @return the formatted membership number
545	     */
546	    private String membershipNumber(String customerCode, java.time.LocalDate registrationDate) {
547	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
548	    }
549	
550	    /**
551	     * Returns the existing owners in the given owner's household, i.e. those sharing its
552	     * deterministic household id (the same last name and postcode). The id is computed via
553	     * {@link HouseholdNormalizer} so that last names differing only in letter case or in incidental
554	     * whitespace are treated as the same household. Centralising how "the same household" is matched
555	     * here keeps that definition in one place for every caller.
556	     *
557	     * @param owner the owner being created, with its household id already assigned
558	     * @return the existing owners in the owner's household (possibly empty)
559	     */
560	    private List<Owner> sameHouseholdOwners(Owner owner) {
561	        String householdId = owner.getHouseholdId();
562	        return existingOwners()
563	            .filter(existing -> householdId.equals(
564	                householdNormalizer.householdId(existing.getLastName(), existing.getPostcode())))
565	            .toList();
566	    }
567	
568	    /**
569	     * Counts the existing owners who share the given first and last name, compared
570	     * case-insensitively. Used to fix an owner's namesake count at creation time.
571	     *
572	     * @param firstName the first name of the owner being created
573	     * @param lastName  the last name of the owner being created
574	     * @return the number of existing owners with a matching first and last name
575	     */
576	    private int countNamesakes(String firstName, String lastName) {
577	        return (int) existingOwners()
578	            .filter(existing -> existing.getFirstName() != null
579	                && existing.getFirstName().equalsIgnoreCase(firstName)
580	                && existing.getLastName() != null
581	                && existing.getLastName().equalsIgnoreCase(lastName))
582	            .count();
583	    }
584	
585	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
586	    @Override
587	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
588	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
589	        if (currentOwner == null) {
590	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
591	        }
592	        currentOwner.setAddress(ownerFieldsDto.getAddress());
593	        currentOwner.setCity(ownerFieldsDto.getCity());
594	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
595	        currentOwner.setLastName(ownerFieldsDto.getLastName());
596	        // Normalize the telephone to canonical E.164 form so it is stored and returned
597	        // consistently with create; an unformattable value is rejected with 400.
598	        currentOwner.setTelephone(telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
599	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
600	        this.clinicService.saveOwner(currentOwner);
601	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
602	    }
603	
604	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
605	    @Transactional
606	    @Override
607	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
608	        Owner owner = this.clinicService.findOwnerById(ownerId);
609	        if (owner == null) {
610	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
611	        }
612	        this.clinicService.deleteOwner(owner);
613	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
614	    }
615	
616	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
617	    @Override
618	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
619	        Owner owner = this.clinicService.findOwnerById(ownerId);
620	        if (owner == null) {
621	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
622	        }
623	        HttpHeaders headers = new HttpHeaders();
624	        Pet pet = petMapper.toPet(petFieldsDto);
625	        owner.setId(ownerId);
626	        pet.setOwner(owner);
627	        pet.getType().setName(null);
628	        this.clinicService.savePet(pet);
629	        PetDto petDto = petMapper.toPetDto(pet);
630	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
631	            .buildAndExpand(pet.getId()).toUri());
632	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
633	    }
634	
635	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
636	    @Override
637	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
638	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
639	        if (currentOwner != null) {
640	            Pet currentPet = this.clinicService.findPetById(petId);
641	            if (currentPet != null) {
642	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
643	                currentPet.setName(petFieldsDto.getName());
644	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
645	                this.clinicService.savePet(currentPet);
646	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
647	            }
648	        }
649	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
650	    }
651	
652	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
653	    @Override
654	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
655	        HttpHeaders headers = new HttpHeaders();
656	        Visit visit = visitMapper.toVisit(visitFieldsDto);
657	        Pet pet = new Pet();
658	        pet.setId(petId);
659	        visit.setPet(pet);
660	        this.clinicService.saveVisit(visit);
661	        VisitDto visitDto = visitMapper.toVisitDto(visit);
662	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
663	            .buildAndExpand(visit.getId()).toUri());
664	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
665	    }
666	
667	
668	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
669	    @Override
670	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
671	        Owner owner = this.clinicService.findOwnerById(ownerId);
672	        if (owner != null) {
673	            Pet pet = owner.getPet(petId);
674	            if (pet != null) {
675	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
676	            }
677	        }
678	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
679	    }
680	}
